"""Original topAndRail header with the original shell's 60px row and fixed example languages."""
from pathlib import Path
import json
r=Path(__file__).resolve().parents[2];o=r/'artifacts/replica/windows-download';src=(r/'docs/replica/source/original.js').read_text().splitlines();defs='\n'.join(s for s in src if s.startswith(('const stages=','const stageNames=','const icons=','const icon=','const t=','function topAndRail()','function press(')))
cases=[{'id':lang+'-'+str(width),'lang':lang,'width':width}for width in [960,1000,1138,1280]for lang in ['ko','en']]
(o/'topbar-original.css').write_bytes((r/'docs/replica/source/original.css').read_bytes())
html='''<!doctype html><meta charset="utf-8"><title>TopBar · original isolation</title><link rel="stylesheet" href="topbar-original.css"><style>body{min-width:1280px}.fixture{position:absolute;left:30px;top:30px}.fixture:not(:first-child){visibility:hidden}.fixture .rail{display:none}.fixture .topbar{height:60px}#top-record{position:fixed;left:30px;top:160px}</style><button id="top-record">Record TopBar</button><div id="fixtures"></div><script>let lang='ko',state={screen:'home',visited:new Set()},requests=[];'''+defs+'\nconst cases='+json.dumps(cases)+''';for(const c of cases){lang=c.lang;const f=document.createElement('section');f.className='fixture';f.dataset.id=c.id;f.style.width=c.width+'px';f.innerHTML=topAndRail();if(c.id!==cases[0].id)f.setAttribute('aria-hidden','true');document.getElementById('fixtures').append(f)}function read(){return [...document.querySelectorAll('.fixture')].map(f=>{const e=f.querySelector('.topbar'),r=e.getBoundingClientRect(),box=x=>{const b=x.getBoundingClientRect();return{x:b.x-r.x,y:b.y-r.y,width:b.width,height:b.height}},button=e.querySelector('.language');return{id:f.dataset.id,width:r.width,height:r.height,brand:box(e.querySelector('.brand')),brandIcon:box(e.querySelector('.brand>.svg')),brandText:box(e.querySelector('.brand span')),preview:box(e.querySelector('.preview')),previewText:e.querySelector('.preview').textContent,language:box(button),languageText:button.textContent,languageName:button.getAttribute('aria-label')}})}document.getElementById('top-record').onclick=async()=>{await document.fonts.ready;const response=await fetch('/evidence/source-sidebar.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({dpr:devicePixelRatio,rows:read(),requests})});if(!response.ok)throw Error('Evidence failed');document.getElementById('top-record').textContent='TopBar recorded'};document.addEventListener('click',e=>{const b=e.target.closest('.language');if(!b||b.disabled)return;press(b);const f=b.closest('.fixture'),next=(f.dataset.inputLanguage||f.dataset.id.split('-')[0])==='ko'?'en':'ko';requests.push({language:next,trusted:e.isTrusted});f.dataset.inputLanguage=next;lang=next;f.innerHTML=topAndRail();document.querySelectorAll('.fixture')[0].style.width='960px'});</script>'''
(o/'topbar.html').write_text(html)
for p in [o/'topbar-cases.json',r/'docs/replica/source/topbar-cases.json']:p.write_text(json.dumps(cases,indent=2)+'\n')
print(len(cases),'original TopBar examples prepared')
